using DotNetPacket.Protocols.Dcerpc;
using Xunit;

namespace DotNetPacket.Core.Tests;

public class LsaPrivilegeTests
{
    // Response stub of a real lsarpc LsarEnumeratePrivileges call captured from
    // impacket against Samba: EnumerationContext, Entries=9, the privilege-array
    // pointer, a conformant max_count, nine LSAPR_POLICY_PRIVILEGE_DEF headers
    // (RPC_UNICODE_STRING name + LUID), then the deferred name buffers. The live
    // rpc-privs example drives the full call; this pins the parser to known bytes.
    private const string EnumPrivilegesStub =
        "";

    [Fact]
    public void ParsePrivileges_ReadsAllNinePrivileges()
    {
        byte[] stub = Convert.FromHexString(EnumPrivilegesStub);

        IReadOnlyList<LsaPrivilege> privs = Lsarpc.ParsePrivileges(stub);

        Assert.Equal(9, privs.Count);
        Assert.Equal("SeMachineAccountPrivilege", privs[0].Name);
        Assert.Equal(6u, privs[0].LuidLow);
        Assert.Equal("SeSecurityPrivilege", privs[8].Name);
        Assert.All(privs, p => Assert.StartsWith("Se", p.Name));
    }
}
